const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.agent}"/></svg>`;
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({mode:'open',rules:{close:true,scam:true,private:true,digest:true},confirmed:false,blocked:false,read:[],replied:{},repliedVia:{},notes:{},mergedAlina:false,journal:[],agentChat:[]});
let state=defaults();try{const saved=JSON.parse(localStorage.getItem('porog-demo-v1')||'null');if(saved)state={...state,...saved,rules:{...state.rules,...saved.rules}}}catch{}
let view='home',filter='all',detailType='',detailId='',articleTab='brief',contactTab='messages',timeFilter='30d',contactQuery='',toastTimer;
const modes={open:{label:'Я открыт миру',icon:'sun',desc:'Важные обращения сразу, каналы — в выпуске.'},focus:{label:'Я занят',icon:'shield',desc:'Сразу только близкие и выбранные важные обращения.'},rest:{label:'Я отдыхаю',icon:'moon',desc:'Подборки и обычные обращения ждут. Близкие могут связаться.'}};
const nav=[['home','Сегодня','home'],['people','Люди','chat'],['world','Мой мир','world'],['memory','Память','memory'],['agent','Агент','agent']];
const connectedServices=['Telegram','WhatsApp','Instagram'];
const chats=[
{id:'alina',name:'Алина',initial:'А',color:'',time:'Сегодня',preview:'Сообщения из трёх подключённых сервисов.',accounts:['Telegram','WhatsApp','Instagram'],dates:[['12 февраля','День рождения']],commits:[['13 сентября · 20:30','Падел с друзьями','Подтверждено в переписке']],messages:[['them','Напомни, мы играем в воскресенье?','10:12','WhatsApp','today'],['me','Да, в 20:30. Корт уже подтверждён.','10:14','WhatsApp','today'],['them','Договорились 🙂','10:15','WhatsApp','today'],['them','Я выложила новые фотографии торта','Вчера, 19:40','Instagram','week'],['me','Видел, получилось красиво','Вчера, 19:51','Instagram','week'],['them','Скинь, пожалуйста, адрес кафе','3 сентября','Telegram','month']]},
{id:'sasha',name:'Саша',initial:'С',color:'blue',time:'14:32',preview:'Договорились на 19:00. Осталось сохранить встречу.',accounts:['Telegram'],dates:[],commits:[['12 сентября · 19:00','Встреча в вашем кафе','Найдено по дате и взаимному согласию']],messages:[['them','Привет! Может, в субботу увидимся?','14:25','Telegram','today'],['me','Да, давай вечером, часов в семь.','14:28','Telegram','today'],['them','Отлично, в 19:00 в нашем кафе. Договорились!','14:32','Telegram','today']]},
{id:'padel',name:'Падел · друзья',initial:'П',color:'green',time:'13:10',preview:'В воскресенье играем в 20:30 вместо 20:00.',accounts:['Telegram'],dates:[],commits:[['13 сентября · 20:30','Падел с друзьями','Время изменено']],messages:[['them','Ребята, наш корт на воскресенье перенесли. Теперь играем в 20:30.','13:08','Telegram','today'],['them','Да, клуб подтвердил. Остальные условия те же.','13:10','Telegram','today']]},
{id:'unknown',name:'Алексей · новый аккаунт',initial:'?',color:'amber',time:'12:41',preview:'Представляется знакомым. Личность не подтверждена.',accounts:['Telegram'],dates:[],commits:[],messages:[['them','Стас, привет! Это Лёша, у меня новый номер. Можешь срочно скинуть 300 евро? Вечером верну.','12:40','Telegram','today'],['them','Только не звони сейчас, я занят. Давай быстрее, очень надо.','12:41','Telegram','today']]}
];
const stories=[{id:'games',category:'games',label:'Игры',title:'Тактика, в которой поле боя меняется со временем',desc:'В трёх каналах обсуждают один деморолик: действия в прошлом меняют укрытия в настоящем. Собрал главное без повторов.',sources:3,mins:2,tag:'Идея для вдохновения',original:'«Показали прототип тактики с двумя временными слоями. Можно изменить прошлое и получить другой маршрут в настоящем. Авторы обещают выложить демо, дата пока не названа».',check:'В демонстрационном примере есть ролик прототипа. По нему нельзя сделать вывод о качестве полной игры. Дата выхода не подтверждена.',channel:'Игровой дневник',time:'Сегодня, 11:20'},{id:'ai',category:'ai',label:'Технологии',title:'Громкое обещание ИИ — что за ним стоит?',desc:'Заголовок обещает «полностью заменить помощника». В тексте речь только о сортировке писем и подготовке черновиков.',sources:4,mins:2,tag:'Есть оговорки',original:'«Помощники больше не нужны! Наш ИИ берёт на себя всю рутину. В первой версии доступны классификация писем и генерация ответов для проверки пользователем».',check:'Формулировка заголовка шире описанных возможностей. Независимых результатов тестирования в этом примере нет. Корректнее говорить о помощи с двумя задачами.',channel:'Технологии рядом',time:'Сегодня, 10:05'},{id:'city',category:'local',label:'Рядом',title:'Один спокойный план на выходные',desc:'Прогулка по парку и кофе с друзьями. Сохрани идею, а время можно согласовать позже.',sources:1,mins:1,tag:'Для себя',original:'«Наш план на воскресенье: встретиться у входа в парк, прогуляться без спешки и заглянуть за кофе. Кто с нами?»',check:'Это предложение провести время, а не проверяемая новость. Дата и участники ещё не согласованы. Погоду и часы работы кафе нужно проверить отдельно.',channel:'Городские прогулки',time:'Сегодня, 09:30'}];
function save(){try{localStorage.setItem('porog-demo-v1',JSON.stringify(state))}catch{}}
function log(text){state.journal.unshift({text,time:new Date().toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'})});save()}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3300)}
function go(next){view=next;filter='all';render();window.scrollTo({top:0,behavior:'instant'})}
function modeButton(){return `<button class="mode" data-action="mode">${icon(modes[state.mode].icon)}${modes[state.mode].label}${icon('down')}</button>`}
function navHtml(mobile=false){return nav.map(([id,label,i])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${!mobile&&id==='people'&&!state.replied.alina?'<span class="count">2</span>':''}</button>`).join('')}
function render(){document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand">${icon('logo')}порог</div><nav class="nav" aria-label="Основная навигация">${navHtml()}</nav><div class="sidebar-bottom"><div class="sidebar-note">Твой ритм.<br>Твои правила доступа.</div><div class="profile"><span class="avatar">С</span><div>Стас<br><small>Личное пространство</small></div><button data-action="settings" aria-label="Настройки">${icon('settings')}</button></div></div></aside><main class="workspace"><header class="topbar"><span class="breadcrumb">Моё пространство / ${nav.find(x=>x[0]===view)[1]}</span><div class="mobile-brand">${icon('logo')}порог</div><div class="top-actions"><span class="demo">ПРОТОТИП</span><button class="icon-button" data-action="settings" aria-label="Настройки защиты">${icon('settings')}</button></div></header><div class="view">${({home:home,people:people,world:world,memory:memory,agent:agent})[view]()}</div><div class="footnote">${icon('lock')}Демо-сценарии · Telegram не подключён</div></main><nav class="mobile-nav" aria-label="Основная навигация">${navHtml(true)}</nav></div>`}
function heading(eye,title,sub,mode=true){return `<div class="heading"><div><div class="eyebrow">${eye}</div><h1>${title}</h1>${sub?`<p class="subline">${sub}</p>`:''}</div>${mode?modeButton():''}</div>`}
function serviceBadge(name){return `<span class="service service-${name.toLowerCase()}">${name}</span>`}
function chatRow(c){const replied=state.replied[c.id],resolved=c.id==='sasha'&&state.confirmed;return `<button class="row contact-row" data-action="chat" data-id="${c.id}"><span class="avatar ${c.color}">${c.initial}</span><div class="body"><div class="contact-name"><h3>${c.name}</h3><span class="service-stack">${c.accounts.map(serviceBadge).join('')}</span></div><p>${replied?'Ты ответил в '+(state.repliedVia[c.id]||c.accounts[0])+': '+esc(replied.slice(0,60)):resolved?'Встреча сохранена · суббота, 19:00':c.preview}</p></div><div class="tail"><span>${c.time}</span>${icon(replied||resolved?'check':'chevron')}</div></button>`}
function home(){return `${heading('Пятница, 11 сентября','Мир может подождать.','Вот то, что заслуживает твоего внимания.')}<div class="grid"><div class="column"><section class="welcome"><div class="welcome-top"><div class="seal">${icon('shield')}</div><div><h2>${state.mode==='open'?'Ты задаёшь ритм.':state.mode==='focus'?'Время для своего.':'Можно выдохнуть.'}</h2><p>${modes[state.mode].desc}</p></div></div><div class="summary-stats"><div><strong>128</strong><span>постов разобрано</span></div><div><strong>3</strong><span>темы в выпуске</span></div><div><strong>${state.blocked?0:1}</strong><span>повод проверить</span></div></div></section><section><div class="section-label"><h2>Ближе к тебе</h2><button class="text-button" data-nav="people">Все обращения ${icon('arrow')}</button></div><div class="card">${chats.slice(0,3).map(chatRow).join('')}</div></section><section class="card card-pad"><div class="card-head"><h2>На ближайшее время</h2>${icon('memory')}</div><div class="memory-preview"><div class="date-tile"><strong>12</strong><span>сент.</span></div><div><h3>Встреча с Сашей</h3><p>Суббота · 19:00 · ваше кафе</p></div></div>${state.confirmed?'<span class="pill green">Встреча сохранена</span>':`<button class="btn soft full" data-action="event">${icon('check')}Сохранить договорённость</button>`}</section></div><div class="column"><section class="digest-preview"><div class="eyebrow">Твой выпуск · 01</div><h2>Меньше шума.<br>Больше интересного.</h2><p>Игры, технологии и один план на выходные. Повторы уже убраны.</p><button class="btn" data-nav="world">Открыть выпуск ${icon('arrow')}</button><div class="meta">${icon('clock')}5 минут · 8 источников</div></section>${state.blocked?`<section class="card card-pad"><div class="risk-title" style="color:#377960">${icon('check')}<h3>Обращение отложено</h3></div><p class="muted" style="font-size:14px">Новый аккаунт Алексея не будет отвлекать в этом демо.</p><button class="text-button" data-action="chat" data-id="unknown">Посмотреть сообщение</button></section>`:`<section class="risk-card"><div class="risk-title">${icon('alert')}<h3>Стоит проверить</h3></div><p>Новый аккаунт представляется знакомым и срочно просит деньги.</p><button class="text-button" data-action="chat" data-id="unknown">Что насторожило ${icon('arrow')}</button></section>`}<section class="card card-pad"><div class="card-head"><h2>Рядом, когда нужен</h2>${icon('agent')}</div><p class="muted" style="font-size:14px">«О чём я договорился?»<br>«Помоги ответить Саше»</p><button class="text-button" data-nav="agent" style="margin-top:15px">Обратиться к агенту ${icon('arrow')}</button></section></div></div>`}
function people(){const q=contactQuery.trim().toLowerCase();const list=chats.filter(c=>(filter==='all'||filter==='important'&&c.id!=='unknown'||filter==='unknown'&&c.id==='unknown')&&(!q||c.name.toLowerCase().includes(q)));return `${heading('Единый мессенджер','Люди','Общение из сервисов, подключённых к Порогу.')}<form class="people-search" id="people-search"><input name="query" value="${esc(contactQuery)}" placeholder="Имя или фамилия"><button class="btn primary">Найти</button>${contactQuery?'<button class="btn" type="button" data-action="clear-people-search">Сбросить</button>':''}</form><div class="connected-line"><span>Подключено</span>${connectedServices.map(serviceBadge).join('')}</div><div class="chips">${[['all','За последний месяц'],['important','Знакомые'],['unknown','Новые люди']].map(([id,label])=>`<button class="chip ${filter===id?'selected':''}" data-filter="${id}">${label}</button>`).join('')}</div>${list.length?`<div class="card large-list">${list.map(chatRow).join('')}</div>`:'<div class="empty-contact"><h2>В знакомых не найдено</h2><p>Поиск по интернету запускается отдельно.</p></div>'}<button class="internet-search" data-action="internet-search">${icon('world')}Искать ${contactQuery?'«'+esc(contactQuery)+'» ':''}в интернете</button><div class="endcap">${icon('check')}<strong>Это все разговоры за последний месяц</strong>Старые контакты доступны через поиск.</div>`}
function world(){const list=stories.filter(s=>filter==='all'||s.category===filter);return `${heading('Личный выпуск · 11 сентября','Твой мир. Без лишнего.','3 темы из 128 постов · примерно 5 минут',false)}<div class="chips">${[['all','Всё интересное'],['games','Игры'],['ai','Технологии'],['local','Рядом']].map(([id,label])=>`<button class="chip ${filter===id?'selected':''}" data-filter="${id}">${label}</button>`).join('')}</div><div class="grid"><div><div class="card">${list.map((s,i)=>`<article class="story"><div class="story-meta"><span class="pill ${s.id==='ai'?'amber':''}">${s.label}</span><span class="meta">${s.mins} мин</span><span class="number">0${i+1}</span></div><h2>${s.title}</h2><p>${s.desc}</p><div class="story-bottom"><button class="text-button" data-action="story" data-id="${s.id}">${state.read.includes(s.id)?'Прочитать снова':'Разобраться'} ${icon('arrow')}</button><span class="meta">${s.sources} ${s.sources===1?'источник':'источника'} · ${state.read.includes(s.id)?'прочитано':s.tag}</span></div></article>`).join('')}</div><div class="endcap">${icon('sun')}<strong>Это весь выпуск.</strong>Можно вернуться к своему дню.</div></div><div class="column"><section class="card card-pad"><div class="card-head"><h2>Почему эти темы?</h2>${icon('eye')}</div><p class="muted" style="font-size:14px">В демо выбраны игры, технологии и жизнь рядом. Интересы определяешь ты.</p><button class="text-button" data-action="sources" style="margin-top:17px">Как устроен отбор ${icon('arrow')}</button></section><div class="notice">${icon('book')}Материалы этого выпуска вымышлены для демонстрации интерфейса.</div></div></div>`}
function memory(){return `${heading('Договорённости','Можно не держать в голове.','У каждого напоминания есть исходный разговор.',false)}<div class="grid"><div><section class="card timeline-card"><div class="timeline-top"><div class="date-tile"><strong>12</strong><span>сент.</span></div><div><h3>Встретиться с Сашей</h3><p class="muted">Суббота, 19:00 · ваше кафе</p><span class="pill ${state.confirmed?'green':'amber'}" style="margin-top:10px">${state.confirmed?'Сохранено · напоминание за час':'Нужно сохранить'}</span></div></div><div class="source">Саша: «Отлично, в 19:00 в нашем кафе. Договорились!»</div><div class="actions">${!state.confirmed?'<button class="btn primary" data-action="event">Сохранить встречу</button>':'<button class="btn" data-action="remove-event">Убрать напоминание</button>'}<button class="btn" data-action="chat" data-id="sasha">Открыть разговор</button></div></section><section class="card timeline-card"><div class="timeline-top"><div class="date-tile"><strong>13</strong><span>сент.</span></div><div><h3>Падел с друзьями</h3><p class="muted">Воскресенье, 20:30</p><span class="pill amber" style="margin-top:10px">Время изменилось: было 20:00</span></div></div><div class="source">Группа: «Наш корт на воскресенье перенесли. Теперь играем в 20:30».</div><div class="actions"><button class="btn" data-action="chat" data-id="padel">Проверить в разговоре</button></div></section>${state.savedIdea?'<section class="card timeline-card"><h3>Прогулка по парку и кофе</h3><p class="muted">Идея на выходные · время пока не выбрано</p><button class="text-button" data-action="story" data-id="city">Открыть источник</button></section>':''}</div><div class="column"><section class="card card-pad"><div class="card-head"><h2>Что сделал агент</h2>${icon('agent')}</div>${state.journal.length?`<div class="journal">${state.journal.slice(0,6).map(j=>`<p>${esc(j.text)}<small>Сегодня, ${esc(j.time)} · демо</small></p>`).join('')}</div>`:'<p class="muted" style="font-size:14px">Здесь появятся сохранённые встречи, ответы и изменения правил.</p>'}</section></div></div>`}
function agent(){return `${heading('Твой помощник','Что возьмём на себя?','Контекст рядом. Последнее слово — за тобой.',false)}<div class="agent-layout"><section class="agent-intro"><div class="agent-mark">${icon('agent')}</div><h2>Я уже собрал главное.</h2><p>Можно спросить о договорённостях, разобрать подозрительное сообщение или подготовить ответ.</p></section><div class="prompt-grid">${['О чём я договорился?','Помоги ответить Саше','Что подозрительного в просьбе денег?','Хочу тишины до вечера'].map(p=>`<button class="prompt" data-action="prompt" data-prompt="${p}">${p}</button>`).join('')}</div><div class="chat-thread" id="agent-thread">${state.agentChat.map(m=>`<div class="bubble ${m.role==='user'?'me':''}">${esc(m.text)}${m.action?`<div class="actions"><button class="btn soft" data-action="${m.action}" ${m.id?`data-id="${m.id}"`:''}>${m.label}</button></div>`:''}</div>`).join('')}</div><form class="composer" id="agent-form"><textarea rows="1" name="message" aria-label="Сообщение агенту" placeholder="Спроси или поручи…" maxlength="1500" required></textarea><button type="submit" aria-label="Отправить агенту">${icon('send')}</button></form><p class="prototype-label">Демо-агент отвечает по сценариям. Переписка остаётся в этом браузере.</p></div>`}
function showDialog(title,body){const d=document.getElementById('detail');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();d.scrollTop=0}
function closeDialog(){document.getElementById('detail').close();detailType='';detailId=''}
function showChat(id,tab=contactTab){const c=chats.find(x=>x.id===id);if(!c)return;detailType='chat';detailId=id;contactTab=tab;const allowed=timeFilter==='7d'?['today','week']:timeFilter==='30d'?['today','week','month']:['today','week','month','all'];let messages=c.messages.filter(m=>allowed.includes(m[4]));if(state.replied[id])messages=[...messages,['me',state.replied[id],'Отправлено в демо',state.repliedVia[id]||c.accounts[0],'today']];let content='';
if(tab==='messages')content=`<div class="history-toolbar"><label>Период<select id="time-filter"><option value="7d" ${timeFilter==='7d'?'selected':''}>7 дней</option><option value="30d" ${timeFilter==='30d'?'selected':''}>30 дней</option><option value="all" ${timeFilter==='all'?'selected':''}>Всё время</option></select></label></div><div class="message-history">${messages.map(([who,t,time,service])=>`<div class="message-wrap ${who==='me'?'mine':''}"><span class="message-source">${serviceBadge(service)}${esc(time)}</span><div class="bubble ${who==='me'?'me':''}">${esc(t)}</div></div>`).join('')}</div>${id==='unknown'?'<div class="risk-box"><h3>Есть признаки риска</h3><p>Новый аккаунт просит срочно перевести деньги и не звонить.</p></div>':`<div class="actions"><button class="btn primary" data-action="reply" data-id="${id}">Написать</button><button class="btn soft" data-action="delegate" data-id="${id}">${icon('agent')}Поручить агенту</button></div>`}`;
if(tab==='commits')content=`<div class="profile-list">${c.commits.length?c.commits.map(x=>`<article><span class="pill green">${esc(x[2])}</span><h3>${esc(x[1])}</h3><p>${esc(x[0])}</p><small>Определено по дате, контрольным словам и согласию обеих сторон.</small></article>`).join(''):'<p class="muted">Подтверждённых договорённостей пока нет.</p>'}</div>`;
if(tab==='dates')content=`<div class="profile-list">${c.dates.length?c.dates.map(x=>`<article><span class="profile-date">${esc(x[0])}</span><h3>${esc(x[1])}</h3></article>`).join(''):'<p class="muted">Важных дат пока нет.</p>'}</div>`;
if(tab==='notes'){const notes=state.notes[id]||[];content=`<form id="note-form" class="note-form"><textarea name="note" maxlength="500" placeholder="Добавить личную заметку…" required></textarea><button class="btn primary">Сохранить</button></form><p class="prototype-label">Заметки добавляешь только ты. Агент их не создаёт.</p><div class="profile-list">${notes.length?notes.map((n,i)=>`<article><p>${esc(n)}</p><button class="text-button danger-text" data-action="delete-note" data-index="${i}">Удалить</button></article>`).join(''):'<p class="muted">Заметок пока нет.</p>'}</div>`}
const tabs=[['messages','Переписка'],['commits','Коммиты'],['dates','Даты'],['notes','Заметки']];showDialog(c.name,`<div class="contact-profile"><span class="avatar ${c.color}">${c.initial}</span><div><h3>${c.name}</h3><div class="service-stack">${c.accounts.map(serviceBadge).join('')}</div></div></div>${id==='alina'&&!state.mergedAlina?`<div class="merge-suggestion"><strong>Похоже, это один человек</strong><p>Алина найдена в Telegram, WhatsApp и Instagram.</p><div class="actions"><button class="btn soft" data-action="merge-alina">Объединить</button><button class="btn" data-action="agent-merge-alina">Поручить агенту</button></div></div>`:id==='alina'?'<p class="merged-status">'+icon('check')+'Аккаунты объединены внутри Порога</p>':''}<div class="dialog-tabs contact-tabs">${tabs.map(([t,l])=>`<button class="${tab===t?'active':''}" data-action="contact-tab" data-tab="${t}" data-id="${id}">${l}</button>`).join('')}</div>${content}`)}
function showEvent(){detailType='event';showDialog('Сохранить встречу',`<div class="memory-preview"><div class="date-tile"><strong>12</strong><span>сент.</span></div><div><h3>Встреча с Сашей</h3><p>Суббота, 19:00 · ваше кафе</p></div></div><div class="source-block">Основание: Саша написал «В 19:00 в нашем кафе. Договорились!» после твоего согласия.</div><div class="check-line">${icon('bell')}Напомнить за час · в этом прототипе системное уведомление не отправляется.</div><button class="btn primary full" data-action="confirm-event">${icon('check')}Сохранить в память</button>`)}
function showReply(id,delegated=false){detailType=delegated?'delegate':'reply';detailId=id;const c=chats.find(c=>c.id===id);if(!c)return;const last=[...c.messages].reverse().find(m=>m[0]==='them'),preferred=last?last[3]:c.accounts[0],text=delegated?(id==='sasha'?'Привет! Я помощник Стаса. Уточни адрес кафе для встречи в субботу в 19:00.':''):'';showDialog(delegated?'Поручение агенту':`Написать · ${c.name}`,`<form id="reply-form"><label class="send-via">Отправить через<select name="service">${c.accounts.map(s=>`<option ${s===preferred?'selected':''}>${s}</option>`).join('')}</select></label><textarea class="reply-box" name="reply" maxlength="2000" required>${esc(text)}</textarea><div class="actions"><button class="btn primary">${delegated?'Подтвердить ответ агента':'Отправить в демо'} ${icon('send')}</button><button type="button" class="btn" data-action="chat" data-id="${id}">Назад</button></div><p class="prototype-label">Показаны только подключённые сервисы. Реальной отправки нет.</p></form>`)}
function showStory(id,tab='brief'){const s=stories.find(s=>s.id===id);if(!s)return;detailType='story';detailId=id;articleTab=tab;showDialog(s.label,`<div class="dialog-tabs" role="tablist" aria-label="Способ просмотра">${[['brief','Суть'],['original','Оригинал'],['check','Проверка']].map(([t,l])=>`<button role="tab" aria-selected="${tab===t}" class="${tab===t?'active':''}" data-action="story-tab" data-tab="${t}">${l}</button>`).join('')}</div><h2 style="font-size:23px;line-height:1.45;margin-bottom:17px">${s.title}</h2>${tab==='brief'?`<p>${s.desc}</p><div class="source-block"><h3>Почему в твоём выпуске</h3>${s.id==='games'?'Выбран интерес «Игры». Эта тема связана с необычными игровыми механиками.':s.id==='ai'?'Выбран интерес «Технологии». Полезно заметить разницу между обещанием и описанными функциями.':'Выбран интерес «Рядом». Это идея для свободного времени.'}</div>`:tab==='original'?`<div class="source-block"><h3>${s.channel}</h3>${s.original}<div class="meta">${s.time} · вымышленный источник</div></div>`:`<div class="risk-box"><h3>Что можно заключить</h3><p>${s.check}</p></div><p>Агент показывает основания и пробелы. Отсутствие найденных проблем не гарантирует достоверность.</p>`}<div class="actions"><button class="btn primary" data-action="read-story" data-id="${id}">${icon('check')}${state.read.includes(id)?'Прочитано':'Отметить прочитанным'}</button>${id==='city'?`<button class="btn" data-action="save-idea">${state.savedIdea?'Идея сохранена':'Сохранить идею'}</button>`:''}</div><p class="prototype-label">Учебный материал для проверки прототипа, не реальная новость.</p>`)}
function showMode(){detailType='mode';showDialog('Какой у тебя сейчас ритм?',`<p>Выбери, какие обращения могут отвлекать. В прототипе это меняет состояние интерфейса.</p>${Object.entries(modes).map(([id,m])=>`<button class="mode-option ${state.mode===id?'selected':''}" data-action="set-mode" data-id="${id}">${icon(m.icon)}<div><h3>${m.label}</h3><p>${m.desc}</p></div>${state.mode===id?icon('check'):''}</button>`).join('')}<div class="notice" style="margin:18px 0 0">${icon('eye')}Сейчас выбранные правила сохраняются только для этого демо. Уведомления телефона не изменяются.</div>`)}
function showSettings(){detailType='settings';const rules=[['close','Близкие могут связаться','Обращения от выбранных близких проходят в любом режиме.'],['scam','Подсвечивать признаки обмана','Показывать причины риска, сохраняя доступ к оригиналу.'],['private','Проверять исходящие данные','Предупреждать перед отправкой телефона, адреса или других личных данных.'],['digest','Объединять посты в выпуски','Убирать повторы. Выпуск заканчивается, лента не продолжается.']];showDialog('Твои правила',`<p>Правила — под твоим контролем. Здесь можно проверить настройки будущего приложения.</p>${rules.map(([key,label,desc])=>`<div class="setting-row"><div class="body"><h3>${label}</h3><p>${desc}</p></div><button class="switch" role="switch" aria-label="${label}" aria-checked="${!!state.rules[key]}" data-action="toggle-rule" data-id="${key}"></button></div>`).join('')}<div class="actions"><button class="btn" data-action="mode">Настроить доступность</button><button class="btn" data-action="reset">${icon('reset')}Начать демо заново</button></div><p class="prototype-label">Эти переключатели демонстрируют настройки. Фоновая защита и подключение к Telegram пока не реализованы.</p>`)}
function setMode(mode){if(!Object.hasOwn(modes,mode))throw new Error('Неизвестный режим');state.mode=mode;log('Выбран режим «'+modes[mode].label+'»');render();return {mode,label:modes[mode].label}}
function askAgent(message){const q=message.trim();if(!q)return;state.agentChat.push({role:'user',text:q});let answer;if(/договор|обещ|помн|встреч/i.test(q))answer={text:`В субботу, 12 сентября, в 19:00 — встреча с Сашей в вашем кафе. ${state.confirmed?'Она уже сохранена.':'Можно сохранить напоминание.'}\n\nВ воскресенье падел перенесли с 20:00 на 20:30. Основание — сообщения группы.`,action:state.confirmed?'chat':'event',id:'sasha',label:state.confirmed?'Открыть разговор':'Сохранить встречу'};else if(/ответ|саш/i.test(q))answer={text:'Могу уточнить у Саши адрес кафе. Покажу текст перед отправкой. В демонстрации ответ останется только здесь.',action:'delegate',id:'sasha',label:'Посмотреть ответ агента'};else if(/деньг|обман|мошенн|подозр/i.test(q))answer={text:'В обращении нового аккаунта есть три признака риска: выдаёт себя за знакомого, торопит с переводом и просит не звонить. Это повод проверить личность через известный контакт, а не доказательство обмана.',action:'chat',id:'unknown',label:'Посмотреть сообщение'};else if(/тишин|вечер|отдых|занят/i.test(q))answer={text:'Можно перейти в режим «Я отдыхаю»: обычные обращения подождут, близкие смогут связаться. Выбери режим. В демо он не управляет настоящими уведомлениями.',action:'mode',label:'Выбрать режим'};else if(/новост|канал|игр|выпуск/i.test(q))answer={text:'В демонстрационном выпуске три темы: необычная игровая механика, разбор громкого обещания ИИ и идея прогулки. Открой «Мой мир», чтобы посмотреть суть и оригиналы.'};else answer={text:'Это демонстрационный агент, без подключения к языковой модели и Telegram. Сейчас можно проверить четыре сценария: договорённости, ответ Саше, подозрительную просьбу денег и режим тишины.'};state.agentChat.push({role:'assistant',...answer});save();render();document.querySelector('#agent-thread')?.scrollIntoView({behavior:'smooth',block:'end'})}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.nav){go(b.dataset.nav);return}if(b.dataset.filter){filter=b.dataset.filter;render();return}const a=b.dataset.action,id=b.dataset.id;switch(a){case'close':closeDialog();break;case'chat':showChat(id);break;case'contact-tab':showChat(id,b.dataset.tab);break;case'merge-alina':case'agent-merge-alina':state.mergedAlina=true;log(a==='agent-merge-alina'?'Агент объединил аккаунты Алины':'Объединены аккаунты Алины');save();showChat('alina',contactTab);toast('Аккаунты объединены внутри Порога');break;case'clear-people-search':contactQuery='';render();break;case'internet-search':showDialog('Поиск в интернете',`<p>Это отдельный поиск. Результаты не смешиваются со знакомыми и не создают контакт автоматически.</p><div class="source-block"><h3>${contactQuery?'Запрос: '+esc(contactQuery):'Сначала введи имя или фамилию'}</h3>В рабочем продукте здесь появятся публичные профили с источниками и отметкой, что личность не подтверждена.</div>`);break;case'delete-note':{const notes=state.notes[detailId]||[];notes.splice(Number(b.dataset.index),1);state.notes[detailId]=notes;save();showChat(detailId,'notes')}break;case'event':showEvent();break;case'confirm-event':if(!state.confirmed){state.confirmed=true;log('Сохранена встреча с Сашей: суббота, 19:00')}closeDialog();render();toast('Встреча сохранена в памяти демо');break;case'remove-event':state.confirmed=false;log('Напоминание о встрече убрано');render();toast('Напоминание убрано. Переписка сохранена.');break;case'reply':showReply(id);break;case'delegate':showReply(id,true);break;case'block':state.blocked=!state.blocked;log(state.blocked?'Подозрительное обращение отложено':'Обращение нового аккаунта возвращено');closeDialog();render();toast(state.blocked?'Отложено в демо. Сообщение сохранено.':'Обращение снова доступно');break;case'verify':showDialog('Проверить личность',`<p>Свяжись с Алексеем по номеру или аккаунту, которым пользовался раньше. Контакт из подозрительного сообщения не подходит для независимой проверки.</p><div class="source-block">Можно спросить: «Ты сейчас просил меня перевести 300 €?»</div><p>В этом демо нет твоей адресной книги, поэтому приложение не может позвонить или подтвердить личность.</p><button class="btn primary full" data-action="chat" data-id="unknown">Вернуться к сообщению</button>`);break;case'story':showStory(id);break;case'story-tab':showStory(detailId,b.dataset.tab);break;case'read-story':if(!state.read.includes(id)){state.read.push(id);save()}render();showStory(id,articleTab);toast('Материал отмечен прочитанным');break;case'save-idea':if(!state.savedIdea){state.savedIdea=true;log('Сохранена идея: прогулка по парку и кофе')}render();showStory('city',articleTab);toast('Идея появилась в памяти');break;case'mode':showMode();break;case'set-mode':setMode(id);closeDialog();toast('Режим: '+modes[id].label);break;case'settings':showSettings();break;case'toggle-rule':state.rules[id]=!state.rules[id];save();b.setAttribute('aria-checked',String(state.rules[id]));toast('Настройка демо сохранена');break;case'reset':showDialog('Начать заново?',`<p>Уберём ответы, сохранённые договорённости и изменения настроек только из этого прототипа.</p><div class="actions"><button class="btn danger" data-action="confirm-reset">Сбросить демо</button><button class="btn" data-action="settings">Оставить как есть</button></div>`);break;case'confirm-reset':state=defaults();save();view='home';filter='all';closeDialog();render();toast('Демонстрация начата заново');break;case'prompt':askAgent(b.dataset.prompt);break;case'sources':showDialog('Как устроен отбор',`<p>Для этого выпуска вручную подготовлены демонстрационные материалы по трём интересам: игры, технологии и жизнь рядом.</p><div class="source-block"><h3>В реальном продукте</h3>Ты выбираешь источники и темы. Агент объединяет повторяющиеся сообщения, сохраняет ссылки на оригиналы и объясняет, почему тема попала в выпуск.</div><p>В текущем прототипе 128 постов и 8 источников — пример объёма, а не результат анализа твоего аккаунта.</p><button class="btn primary full" data-action="close">Понятно</button>`);break}});
document.addEventListener('submit',e=>{if(e.target.id==='people-search'){e.preventDefault();contactQuery=String(new FormData(e.target).get('query')||'').trim();render();return}if(e.target.id==='note-form'){e.preventDefault();const note=String(new FormData(e.target).get('note')||'').trim();if(!note)return;(state.notes[detailId]||(state.notes[detailId]=[])).unshift(note);save();showChat(detailId,'notes');toast('Личная заметка сохранена');return}if(e.target.id==='agent-form'){e.preventDefault();askAgent(new FormData(e.target).get('message')||'')}if(e.target.id==='reply-form'){e.preventDefault();const fd=new FormData(e.target),text=String(fd.get('reply')||'').trim(),service=String(fd.get('service')||'');if(!text)return;const id=detailId;state.replied[id]=text;state.repliedVia[id]=service;log('Сохранён ответ для '+chats.find(x=>x.id===id).name+' через '+service);save();render();showChat(id);toast('Ответ отправлен через '+service+' только в демо')}});
document.getElementById('detail').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
document.getElementById('detail').addEventListener('change',e=>{if(e.target.id==='time-filter'){timeFilter=e.target.value;showChat(detailId,'messages')}});
document.getElementById('detail').addEventListener('close',()=>{detailType='';detailId=''});
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'get_porog_demo_state',title:'Состояние прототипа',description:'Read the current local demonstration state. No real Telegram data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected empty object');return{mode:state.mode,meetingSaved:state.confirmed,requestDeferred:state.blocked,readStories:[...state.read]}}},{name:'set_porog_demo_mode',title:'Изменить режим демо',description:'Change the visible availability mode in the prototype only. Does not change real notifications.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['open','focus','rest']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.mode!=='string'||Object.keys(input).some(k=>k!=='mode'))throw new Error('Invalid mode input');return setMode(input.mode)}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
